const input = $input.first().json;
const headers = input.headers || {};
const body = input.body || {};
const expectedToken = (typeof $env !== 'undefined' && $env.N8N_WEBHOOK_TOKEN) || (typeof process !== 'undefined' && process.env.N8N_WEBHOOK_TOKEN) || '';
const actualToken = headers['x-servicedesk-token'] || headers['X-ServiceDesk-Token'] || headers['X-Servicedesk-Token'] || '';
const response = (statusCode, code, message, details = {}) => [{ json: { shouldSend: false, statusCode, response: { error: { code, message, ...details } } } }];
if (!expectedToken || actualToken !== expectedToken) return response(401, 'unauthorized', 'Токен webhook отсутствует или некорректен.');
if (body.attachment || body.attachments || body.files) return response(400, 'attachments_not_supported', 'Attachments are not supported in v1.');
const split = value => String(value).split(/[;,]/).map(v => v.trim()).filter(Boolean);
const list = value => Array.isArray(value) ? value.flatMap(split) : split(value || '');
const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const invalid = values => values.filter(v => !emailRe.test(v));
const to = list(body.to);
const cc = list(body.cc);
const bcc = list(body.bcc);
const replyTo = String(body.replyTo || body.reply_to || '').trim();
const subject = String(body.subject || '').trim();
const textBody = typeof body.body === 'string' ? body.body : '';
if (to.length === 0) return response(400, 'missing_to', 'Поле to обязательно.');
if (!subject) return response(400, 'missing_subject', 'Поле subject обязательно.');
if (!textBody.trim()) return response(400, 'missing_body', 'Поле body обязательно.');
const bad = [...invalid(to), ...invalid(cc), ...invalid(bcc), ...(replyTo && !emailRe.test(replyTo) ? [replyTo] : [])];
if (bad.length) return response(400, 'invalid_email', 'Некорректный email адрес.', { addresses: bad });
const requestId = String(body.request_id || body.requestId || `n8n-mail-${Date.now()}`).trim();
return [{ json: { shouldSend: true, statusCode: 200, requestId, to, cc, bcc, toEmail: to.join(', '), ccEmail: cc.join(', '), bccEmail: bcc.join(', '), replyTo, subject, body: textBody } }];

const result = $input.first().json || {};
const err = result.error || result.message?.error;
if (err) {
  const message = typeof err === 'string' ? err : (err.message || 'Email Send node failed.');
  return [{ json: { statusCode: 502, response: { error: { code: 'email_send_failed', message } } } }];
}
return [{ json: { statusCode: 200, response: { status: 'sent' } } }];
